(()=>{
'use strict';
const {activities,makeQuestion,evaluate,shapes}=MathPark,A=ParkArt,$=s=>document.querySelector(s),app=$('#app');
let stored={};try{stored=JSON.parse(localStorage.getItem('math-park-v1')||'{}')||{};}catch{}
const state={screen:'intro',id:null,playerName:stored.playerName||'',voice:stored.voice!==false,level:stored.level||1,auto:stored.auto!==false,sound:stored.sound===true,stars:0,badges:{},correct:0,clean:0,attempts:0,question:null,built:0,answered:false,hint:false};
let lastFocus=null,audioCtx=null;
const save=()=>{try{const data={playerName:state.playerName,avatar:state.avatar,voice:state.voice,level:state.level,auto:state.auto,sound:state.sound,stars:state.stars,badges:state.badges};localStorage.setItem('math-park-v1',JSON.stringify(data));if(state.playerName)localStorage.setItem('math-park-player:'+state.playerName.toLocaleLowerCase('pt-BR'),JSON.stringify(data));}catch{}};
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const WELCOME='Bem-vindos ao Parque dos Números. Você não precisa de um ingresso, mas precisamos do seu nome.';
const crew=[{id:'lia',name:'Lia'},{id:'kenji',name:'Kenji'},{id:'maya',name:'Maya'},{id:'tom',name:'Tom'}];
state.avatar=crew.some(p=>p.id===stored.avatar)?stored.avatar:'lia';
function crewPicker(){return `<section class="crew-section" aria-label="Escolha seu parceiro de aventura"><div class="crew-intro"><h2>Uma turma, muitas descobertas</h2><p>Quem vai brincar com você?</p></div><div class="crew-row">${crew.map(p=>`<button class="crew-choice ${state.avatar===p.id?'selected':''}" data-avatar="${p.id}" aria-label="Escolher ${p.name} como parceiro de aventura" aria-pressed="${state.avatar===p.id}"><span class="crew-portrait" style="background-image:url('assets/avatar-${p.id}.webp')"></span><b>${p.name}</b>${state.avatar===p.id?'<span class="crew-check" aria-hidden="true">★</span>':''}</button>`).join('')}</div></section>`;}
let introSpoken=false,entering=false,speechSerial=0;
async function speak(text,force=false,clip=null){if(!state.voice&&!force)return;const serial=++speechSerial;ParkAudio.stop();if('speechSynthesis'in window)speechSynthesis.cancel();if(!clip&&text.startsWith(WELCOME))clip='welcome';if(clip&&await ParkAudio.play(clip))return;if(serial!==speechSerial)return;if(await ParkAudio.synthesize(text))return;if(serial!==speechSerial)return;await ParkAudio.play(state.screen==='game'?'activities.'+state.id:'entry');}
function stopVoice(){speechSerial++;ParkAudio.stop();if('speechSynthesis'in window)speechSynthesis.cancel();$('.intro-screen')?.classList.remove('leo-speaking');}
function renderIntro(){CarRide.dispose();BalloonDivision.dispose();stopVoice();state.screen='intro';introSpoken=false;entering=false;document.title='Parque dos Números';app.innerHTML=`<main class="intro-screen"><div class="curtain-valance"></div><div class="curtain left"></div><div class="curtain right"></div><div class="spotlight one"></div><div class="spotlight two"></div>${Array.from({length:28},(_,i)=>`<i class="twinkle" style="left:${8+(i*31)%84}%;top:${8+(i*17)%75}%;animation-delay:${i*.17}s"></i>`).join('')}<div class="intro-top"><button data-action="intro-voice" class="voice-btn">${state.voice?'♫ Voz ligada':'♫ Voz desligada'}</button></div><div class="intro-content"><div class="intro-copy"><img class="intro-logo" src="assets/logo.svg" alt="Parque dos Números"><div class="intro-kicker">O grande espetáculo da matemática</div><h1>Você não precisa<br>de um <em>ingresso...</em></h1><p class="intro-line">...mas precisamos do seu nome!<br>Eu sou o Leo. Como você se chama?</p><form class="name-card" id="player-form"><label for="player-name">Qual é o seu nome?</label><input id="player-name" name="player-name" type="text" maxlength="30" required autocomplete="off" spellcheck="false" placeholder="Escreva seu nome aqui" value="${esc(state.playerName)}" aria-describedby="name-note"><button class="enter-park" type="submit">Entrar no picadeiro</button><small id="name-note">Seu nome e suas conquistas ficam neste navegador.</small></form><div class="opening-control"><button data-action="intro-read" class="voice-btn">♫ Ouvir o Leo</button><span aria-hidden="true">✦</span><button data-action="intro-read">Boas-vindas ao parque</button></div></div><div class="intro-leo"><div class="leo-shadow"></div><img src="assets/leo-apresentador.webp" alt="Leo, um leão sorridente com cartola, casaca vermelha e detalhes dourados, convidando você para o circo"></div></div><div class="theater-floor"></div></main>`;window.scrollTo({top:0,behavior:'instant'});}
function enterPark(){if(entering)return;const input=$('#player-name'),name=input.value.trim().replace(/\s+/g,' ').slice(0,30);if(!name){input.setCustomValidity('Escreva seu nome para entrar no parque.');input.reportValidity();return;}input.setCustomValidity('');state.playerName=name;try{const p=JSON.parse(localStorage.getItem('math-park-player:'+name.toLocaleLowerCase('pt-BR'))||'null');state.stars=p?.stars||0;state.badges=p?.badges||{};if(crew.some(x=>x.id===p?.avatar))state.avatar=p.avatar;state.level=Math.max(1,Math.min(3,p?.level||1));state.auto=p?.auto!==false;}catch{state.stars=0;state.badges={};state.level=1;}save();entering=true;speak(`Muito bem, ${name}! Seja bem-vindo ao Parque dos Números. Escolha uma atração e vamos brincar de matemática!`);$('.intro-screen').classList.add('leaving');setTimeout(()=>{renderHome();entering=false;},matchMedia('(prefers-reduced-motion: reduce)').matches?0:600);}
const announce=t=>{$('#announcer').textContent=t;};
const mascot=()=>A.svg(A.clown(50,59,.48),'0 0 100 105');
const fmtTime=n=>`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;
function tone(success=true){if(!state.sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();[success?523:330,success?659:294,success?784:330].forEach((f,i)=>{let o=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime+i*.11;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.07,t+.02);g.gain.exponentialRampToValueAtTime(.0001,t+.2);o.connect(g);g.connect(audioCtx.destination);o.start(t);o.stop(t+.21);});}catch{}}
function read(){const q=state.question;speak(q.prompt+(q.id==='cars'?` Quanto é ${q.a} ${q.op==='+'?'mais':'menos'} ${q.b}? Escolha uma pista e acelere.`:''),true,ParkAudio.local?null:'activities.'+state.id);}
function header(){return `<header><button class="brand" data-action="home" aria-label="Parque dos Números, início"><span class="brand-copy">Parque dos Números</span></button><div class="toolbar"><span class="hello-player">Olá, ${esc(state.playerName)}!</span><div class="pill star-count" aria-label="${state.stars} estrelas conquistadas"><span class="mini">★</span><span id="star-total">${state.stars}</span><span class="tool-label">estrelas</span></div><button class="pill voice-button ${state.voice?'':'off'}" data-action="voice" aria-label="${state.voice?'Desativar':'Ativar'} voz do Leo"><span class="mini">♫</span><span class="tool-label">Voz ${state.voice?'ligada':'desligada'}</span></button><button class="pill" data-action="settings" aria-label="Abrir configurações"><span class="mini">⚙</span><span class="tool-label">Educador</span></button></div></header>`;}
function card(a){return `<button class="activity-card" data-activity="${a.id}" style="--card-color:${a.color};--card-ink:${a.ink}" aria-label="Jogar ${a.name}: ${a.topic}"><div class="card-art">${a.extra?'<span class="ribbon">NOVA ATRAÇÃO</span>':''}${state.badges[a.id]?'<span class="badge-earned" title="Atração concluída">★</span>':''}<img class="painted-art" src="assets/${a.id}.webp" alt="" loading="lazy"></div><div class="card-info"><h3>${a.name}</h3><span class="play-dot" aria-hidden="true">▶</span><p>${a.topic}</p></div></button>`;}
function renderHome(){CarRide.dispose();BalloonDivision.dispose();state.screen='home';state.id=null;app.innerHTML=header()+`<main class="home screen-enter"><span class="cloud one"></span><span class="cloud two"></span><section class="welcome"><div><div class="eyebrow">Um mundo de descobertas</div><h1>Respeitável público,<br>vamos <em>brincar de aprender?</em></h1><p>${esc(state.playerName)}, escolha uma atração! Aqui, cada descoberta é um pequeno grande espetáculo.</p></div><div class="welcome-art">${A.svg(`${A.tent(190,125,.78)}${A.clown(324,140,.55)}${A.star(63,46,.9)}${A.star(321,39,.65)}`,'0 0 400 230')}</div></section>${crewPicker()}<div class="section-head"><h2>Por onde começa a aventura?</h2><p>5 atrações para explorar no seu ritmo</p></div><section class="activity-grid main-grid" aria-label="Atrações do parque">${activities.filter(a=>!a.extra).map(card).join('')}</section><div class="section-head extra-head"><h2>O circo continua!</h2><p>Mais matemática, novas descobertas</p></div><section class="activity-grid extra-grid" aria-label="Mais atividades de matemática">${activities.filter(a=>a.extra).map(card).join('')}</section><footer class="home-foot"><span>✦</span> Sem pressa. Sem perder vidas. Com muitas descobertas. <span>✦</span><button data-action="opening">Trocar jogador</button></footer></main>`;}
function start(id){if(!activities.some(a=>a.id===id))return;state.screen='game';state.id=id;state.correct=0;state.clean=0;nextQuestion();window.scrollTo({top:0,behavior:'instant'});}
function nextQuestion(){CarRide.dispose();BalloonDivision.dispose();state.question=makeQuestion(state.id,state.level);state.attempts=0;state.built=0;state.answered=false;state.hint=false;renderGame();announce(state.question.prompt);if(state.voice){if(state.correct===0)speak(state.question.prompt,false,'activities.'+state.id);else read();}}
function tokens(n,interactive=false){return Array.from({length:n},(_,i)=>interactive?`<button class="token" data-action="count-star" aria-label="Contar estrela ${i+1}" aria-pressed="false">★</button>`:`<span class="token" aria-hidden="true">★</span>`).join('');}
function clowns(n){return n?Array.from({length:n},(_,i)=>`<img class="performer-sprite" src="assets/avatar-${crew[i%4].id}.webp" alt="" style="--i:${i%5}">`).join(''):'<span style="color:#7c9ab0;font-size:30px" aria-hidden="true">?</span>';}
function stage(q){
 if(q.id==='division')return '<div id="division-container"></div>';
 if(q.id==='cars')return '<div id="car-ride-container"></div>';
 if(q.id==='clowns')return `<div class="stage"><div class="groups ${q.b?'three':''}"><div class="clown-platform"><div class="little-clowns">${clowns(q.a)}</div><b class="platform-count">${q.a}</b></div>${q.b?`<div class="clown-platform violet"><div class="little-clowns">${clowns(q.b)}</div><b class="platform-count">${q.b}</b></div>`:''}<div class="clown-platform blue"><div class="little-clowns" id="built-clowns">${clowns(state.built)}</div><b class="platform-count" id="built-number" aria-live="polite">${state.built}</b></div></div></div><div class="equation">${q.a}${q.b?' + '+q.b:''} + <span id="built-equation">${state.built}</span> = ${q.total}</div>`;
 if(q.id==='factory')return `<div class="stage"><div class="factory-groups">${Array.from({length:q.groups},(_,i)=>`<div class="smile-group" aria-label="Grupo ${i+1}: ${q.each} sorrisos">${Array(q.each).fill('<span class="smile" aria-hidden="true">⌣</span>').join('')}</div>`).join('')}</div></div><div class="equation">${q.groups} × ${q.each} = ?</div>`;
 if(q.id==='patterns')return `<div class="stage"><div class="sequence" aria-label="Sequência: ${q.series.map(v=>q.numeric?v:shapeName(v)).join(', ')}, ponto de interrogação">${q.series.map(v=>`<div class="sequence-item">${q.numeric?v:A.svg(A.shape(v,50,50,65),'0 0 100 100')}</div>`).join('')}<div class="sequence-item missing">?</div></div></div>`;
 if(q.id==='bubbles')return `<div class="stage">${q.count?`<div class="bubble-stars">${tokens(q.count,true)}</div>`:`<div class="place-values">${q.hundreds?`<div class="place-box"><b>${q.hundreds}</b><span>centenas</span></div>`:''}<div class="place-box"><b>${q.tens}</b><span>dezenas</span></div><div class="place-box"><b>${q.units}</b><span>unidades</span></div></div>`}</div>`;
 if(q.id==='clock')return `<div class="stage stage-clock" role="img" aria-label="Relógio analógico com ponteiro curto no horário e ponteiro longo nos minutos">${A.svg(A.clock(150,137,q.hour,q.minute,112),'0 0 300 280')}</div>`;
 if(q.id==='tickets')return `<div class="stage"><div class="ticket-art"><small>Circo das descobertas</small>${A.svg(A.star(50,35,1.4),'0 0 100 65')}<strong>R$ ${q.price},00</strong><p>${q.count===1?'1 ingresso':q.count+' ingressos por esse preço cada'}</p></div>${q.level>1?`<div class="payment"><small>VOCÊ PAGOU</small><strong>R$ ${q.paid}</strong><small>Qual é o troco?</small></div>`:''}</div>`;
 if(q.id==='shapes')return `<div class="stage stage-shapes">${q.level===2?A.svg(A.shape(q.target.id,100,100,145),'0 0 200 200'):`<div class="shape-parade">${['circle','triangle','square','rectangle'].map((s,i)=>A.svg(A.shape(s,50,50,66),'0 0 100 100')).join('')}</div>`}</div>`;
}
function shapeName(id){return shapes.find(s=>s.id===id)?.name||id;}
function renderAnswers(q){if(q.id==='cars'||q.id==='division')return '';if(q.type==='build')return `<div class="builder"><button class="build-btn" data-action="remove-clown" aria-label="Retirar um palhaço" ${state.built===0?'disabled':''}>−</button><button class="build-btn" data-action="add-clown" aria-label="Adicionar um palhaço">+</button><button class="primary" data-action="check-build">Conferir</button></div>`;
 return `<div class="answers" aria-label="Escolha uma resposta">${q.options.map((v,i)=>`<button class="answer ${q.id==='bubbles'?'answer-bubble':''} ${typeof v==='string'?'answer-shape':''}" data-answer="${v}" data-type="${typeof v}" aria-label="${typeof v==='string'?shapeName(v):q.id==='clock'?fmtTime(v):q.id==='tickets'?v+' reais':v}">${typeof v==='string'?A.svg(A.shape(v,50,50,65),'0 0 100 100')+`<span>${shapeName(v)}</span>`:q.id==='clock'?fmtTime(v):q.id==='tickets'?`R$ ${v}`:v}</button>`).join('')}</div>`;
}
function renderGame(){CarRide.dispose();BalloonDivision.dispose();const q=state.question,a=activities.find(x=>x.id===state.id);app.innerHTML=header()+`<main class="game-shell screen-enter ${q.id==='cars'?'is-cars':''}" style="--scene-url:url('assets/${q.id}.webp')"><div class="game-top"><button class="back" data-action="home">Ver atrações</button><div class="game-title"><h1>${a.name}</h1><p>${a.topic}</p></div><span class="level" id="level-label">Nível ${state.level} · ${['Descobrir','Explorar','Desafiar'][state.level-1]}</span></div><section class="game-panel"><div class="progress-bar"><div class="dots" aria-label="${state.correct} de 5 desafios concluídos">${Array.from({length:5},(_,i)=>`<span class="dot ${i<state.correct?'done':''}" aria-hidden="true">${i<state.correct?'★':''}</span>`).join('')}<span class="progress-label">${state.correct}/5</span></div><div class="streak">${state.auto?'Dois acertos de primeira<br>abrem um novo nível':'Vamos no seu ritmo'}</div></div><div class="question-area"><h2 id="question-title" tabindex="-1">${q.prompt}</h2><button class="listen" data-action="read">♫ Ouvir o desafio</button></div>${stage(q)}<div id="answer-area">${renderAnswers(q)}</div><div id="hint-panel"></div><div class="feedback-row"><div class="mascot">${mascot()}</div><div class="feedback-copy" id="feedback"><strong>Você consegue descobrir!</strong><p>${q.type==='build'?'Use + e − para completar o palco.':'Observe com calma e escolha sua resposta.'}</p></div><button class="secondary hint" data-action="hint">✦ Uma dica</button></div></section><p class="game-note">Seu progresso fica salvo neste navegador. Você pode mudar o nível em Educador.</p></main>`;if(q.id==='cars'){CarRide.mount($('#car-ride-container'),q,value=>check(value));decorateDrivers();}if(q.id==='division')BalloonDivision.mount($('#division-container'),q,value=>check(value));}
function showHint(){if(state.answered)return;state.hint=true;state.clean=0;$('#hint-panel').innerHTML=`<div class="hint-panel">${state.question.hint}</div>`;announce(state.question.hint);speak(state.question.hint,false,ParkAudio.local?null:'hints.'+state.id);}
function check(value,button){if(state.answered)return;const q=state.question;if(!evaluate(q,value)){state.attempts++;state.clean=0;if(button){button.classList.add('wrong');button.setAttribute('aria-label',button.getAttribute('aria-label')+', tente outra resposta');setTimeout(()=>button.classList.remove('wrong'),550);}$('#feedback').innerHTML=`<strong>Ainda não. Vamos tentar de outro jeito?</strong><p>${state.attempts>1?q.hint:'Olhe mais uma vez. Você pode tentar quantas vezes quiser.'}</p>`;announce('Ainda não. '+(state.attempts>1?q.hint:'Tente outra vez.'));tone(false);speak('Vamos tentar de novo, '+state.playerName+'. '+(state.attempts>1?q.hint:'Observe com calma. Você consegue!'),false,'retry');return;}
 state.answered=true;state.correct++;state.stars++;if(state.attempts===0&&!state.hint)state.clean++;else state.clean=0;
 let advanced=false;if(state.auto&&state.clean>=2&&state.level<3){state.level++;state.clean=0;advanced=true;}
 if(button)button.classList.add('correct');celebrateStage(q);document.querySelectorAll('[data-answer],.build-btn,[data-action="check-build"]').forEach(b=>b.disabled=true);
 $('#feedback').innerHTML=`<strong>${advanced?'Você abriu um novo nível!':'Muito bem, '+esc(state.playerName)+'!'} <span aria-hidden="true">★</span></strong><p>${q.explain}${advanced?' O próximo desafio será um pouquinho maior.':''}</p>`;
 $('.feedback-row>.hint').outerHTML=`<button class="primary" data-action="next">${state.correct>=5?'Ver conquista':'Próximo desafio'}</button>`;
 $('#star-total').textContent=state.stars;$('.star-count').setAttribute('aria-label',state.stars+' estrelas conquistadas');$('.dots').innerHTML=Array.from({length:5},(_,i)=>`<span class="dot ${i<state.correct?'done':''}" aria-hidden="true">${i<state.correct?'★':''}</span>`).join('')+`<span class="progress-label">${state.correct}/5</span>`;$('.dots').setAttribute('aria-label',state.correct+' de 5 desafios concluídos');save();tone();speak('Muito bem, '+state.playerName+'! '+q.explain+(advanced?' Você abriu um novo nível!':''),false,'success');announce('Muito bem! '+q.explain+(advanced?' Você abriu um novo nível.':''));
}
function celebrateStage(q){
 const stage=$('.stage');if(!stage)return;stage.classList.add('celebrating');
 if(q.id==='patterns'){const slot=$('.sequence-item.missing');slot.classList.remove('missing');slot.classList.add('revealed');slot.innerHTML=q.numeric?q.answer:A.svg(A.shape(q.answer,50,50,65),'0 0 100 100');}
 if(q.id==='tickets'){$('.ticket-art').insertAdjacentHTML('beforeend','<span class="ticket-stamp">ENTRADA LIBERADA</span>');}
 if(q.id==='shapes'&&typeof q.answer==='string'){stage.innerHTML=A.svg(A.shape(q.answer,100,100,135),'0 0 200 200');}
 if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const burst=document.createElement('div');burst.className='stage-stars';burst.innerHTML=Array.from({length:15},(_,i)=>`<i style="--x:${Math.cos(i*2.4)*145}px;--y:${Math.sin(i*2.4)*100}px;animation-delay:${i%3*.04}s">★</i>`).join('');stage.append(burst);setTimeout(()=>burst.remove(),1300);}
}
function decorateDrivers(){const player=$('.car-ride__player');if(player)player.insertAdjacentHTML('beforeend',`<span class="car-ride__pilot" style="background-image:url('assets/avatar-${state.avatar}.webp')"></span>`);document.querySelectorAll('.car-ride__target-body').forEach((target,i)=>target.insertAdjacentHTML('beforeend',`<span class="car-ride__pilot" style="background-image:url('assets/avatar-${crew[i%4].id}.webp')"></span>`));}
function confetti(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const d=document.createElement('div');d.className='confetti';d.innerHTML=Array.from({length:35},(_,i)=>`<i style="left:${Math.random()*100}%;background:${['#ffca61','#f48fae','#a291d9','#69c9b5'][i%4]};animation-delay:${Math.random()*.8}s;transform:rotate(${Math.random()*150}deg)"></i>`).join('');document.body.append(d);setTimeout(()=>d.remove(),3500);}
function modal(content,cls=''){lastFocus=document.activeElement;const o=document.createElement('div');o.className='overlay';o.innerHTML=`<section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-action="close-modal" aria-label="Fechar">×</button>${content}</section>`;document.body.append(o);o.querySelector('button').focus();}
function closeModal(){document.querySelector('.overlay')?.remove();lastFocus?.focus();}
function complete(){const a=activities.find(x=>x.id===state.id);state.badges[a.id]=(state.badges[a.id]||0)+1;save();modal(`<div class="complete-art"><img src="assets/${a.id}.webp" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:20px"></div><h2 id="modal-title">Um espetáculo de descobertas!</h2><div class="complete-stars" aria-hidden="true">★★★</div><p>${esc(state.playerName)}, você completou 5 desafios em <strong>${a.name}</strong> e conquistou 5 estrelas. O parque tem muito mais para explorar!</p><div class="modal-actions"><button class="primary" data-action="replay">Brincar de novo</button><button class="secondary" data-action="finish-home">Escolher outra atração</button></div>`,'complete');confetti();speak('Parabéns, '+state.playerName+'! Você completou cinco desafios. Que espetáculo!',false,'complete');}
function settings(){modal(`<h2 id="modal-title">No ritmo de cada criança</h2><p>Escolha o ponto de partida. As atividades não têm limite de tempo e permitem novas tentativas.</p><div class="settings-group"><label>Nível dos desafios</label><div class="difficulty">${['Descobrir','Explorar','Desafiar'].map((x,i)=>`<button data-level="${i+1}" class="${state.level===i+1?'active':''}" aria-pressed="${state.level===i+1}">${i+1} · ${x}</button>`).join('')}</div></div><label class="setting-row" for="auto-level">Avançar após dois acertos de primeira<input id="auto-level" type="checkbox" ${state.auto?'checked':''}></label><p>Uma dica ou um erro interrompe essa sequência. A criança pode continuar tentando, sem perder estrelas.</p><label class="setting-row" for="voice-setting">Voz do Leo e leitura automática<input id="voice-setting" type="checkbox" ${state.voice?'checked':''}></label><label class="setting-row" for="sound-setting">Sons suaves de acerto e tentativa<input id="sound-setting" type="checkbox" ${state.sound?'checked':''}></label><p>Os níveis ampliam os números e a complexidade. Não representam uma avaliação ou correspondência rígida com o ano escolar.</p><button class="primary" data-action="save-settings">Pronto para brincar</button>`);}
function toast(t){let d=document.createElement('div');d.className='tiny-toast';d.textContent=t;document.body.append(d);setTimeout(()=>d.remove(),3500);}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;
 if(b.dataset.avatar){state.avatar=b.dataset.avatar;save();renderHome();speak(crew.find(p=>p.id===state.avatar).name+' vai brincar com você. Todos os personagens podem explorar todas as atrações!');return;}
 if(b.dataset.activity){start(b.dataset.activity);return;}
 if(b.dataset.answer!==undefined){check(b.dataset.type==='number'?Number(b.dataset.answer):b.dataset.answer,b);return;}
 if(b.dataset.level){document.querySelectorAll('[data-level]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});return;}
 switch(b.dataset.action){case'home':stopVoice();renderHome();break;case'opening':renderIntro();break;case'intro-read':introSpoken=true;speak(WELCOME+' Eu sou o Leo! Como você se chama?',true);break;case'intro-voice':state.voice=!state.voice;if(!state.voice)stopVoice();save();b.textContent=state.voice?'♫ Voz ligada':'♫ Voz desligada';break;case'voice':state.voice=!state.voice;save();if(state.voice)speak('Olá, '+state.playerName+'! A voz do Leo está ligada.');else stopVoice();refreshHeader();break;case'sound':state.sound=!state.sound;save();if(state.sound)tone();const old=state.screen;old==='home'?renderHome():refreshHeader();break;case'settings':settings();break;case'close-modal':closeModal();break;case'save-settings':{const level=Number($('.difficulty .active').dataset.level),changed=level!==state.level;state.level=level;state.auto=$('#auto-level').checked;state.sound=$('#sound-setting').checked;state.voice=$('#voice-setting').checked;if(!state.voice)stopVoice();state.clean=0;save();closeModal();if(state.screen==='game'){if(changed&&state.correct<5)nextQuestion();else refreshHeader();}else renderHome();break;}case'read':read();break;case'hint':showHint();break;case'count-star':{let on=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(on));b.classList.toggle('counted',on);break;}case'add-clown':case'remove-clown':{if(state.answered)return;state.built=Math.max(0,Math.min(30,state.built+(b.dataset.action==='add-clown'?1:-1)));$('#built-clowns').innerHTML=clowns(state.built);$('#built-number').textContent=state.built;$('#built-equation').textContent=state.built;$('[data-action="remove-clown"]').disabled=state.built===0;$('[data-action="add-clown"]').disabled=state.built===30;break;}case'check-build':check(state.built,b);break;case'next':state.correct>=5?complete():nextQuestion();break;case'replay':{let id=state.id;closeModal();start(id);break;}case'finish-home':closeModal();renderHome();break;
 }
});
function refreshHeader(){const h=document.createElement('div');h.innerHTML=header();$('header').replaceWith(h.firstElementChild);}
document.addEventListener('keydown',e=>{const o=$('.overlay');if(o){if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){let f=[...o.querySelectorAll('button,input')].filter(x=>!x.disabled),first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}});
document.addEventListener('submit',e=>{if(e.target.id==='player-form'){e.preventDefault();enterPark();}});
document.addEventListener('input',e=>{if(e.target.id==='player-name')e.target.setCustomValidity('');});
document.addEventListener('focusin',e=>{if(e.target.id==='player-name'&&!introSpoken&&state.voice){introSpoken=true;speak(WELCOME+' Eu sou o Leo. Como você se chama?');}});
renderIntro();
})();
